add('21_001','斜构图水面全景，青和春子背向站在左前，五名兜帽群组在右下远景，群像密壁充满右上。',['青','春子','五名兜帽来者','水面','群像'],[],['两人站立背向','青在春子右侧','群组在右下远方'],'下缘斜向水面，后方密集群像和低白雾',[],'State，切回两人已站立的新源状态，来者群组远处；不补放下、换手和走路过程。',['两人背向站立，群组远处',['青白发余摆收弱','春子裙缘短摆，水纹沿下方掠过'],'重新建立对话双方距离，重复空间明确','两人站在原处，群组未移动'],'与20胸像的不可见下肢不冲突；此处真实源状态为并立，不能延续已经结束的抱持。',3,['24mm低角度斜轴全景，青和春子背向站在左前，青位于右、春子位于左，五名兜帽来者在右下远景；水面斜穿下缘，密集群像填右上。机位沿水面轻缓向前推近，稳定在双人背影和远处群组同框。','青的长白发末端轻摆后落定，春子黑裙的下缘随低处气流短短晃动。两人背向镜头站在水面上，远处五名兜帽来者保持群聚；细水纹沿下方斜向掠过，足旁暗倒影轻颤。','深灰蓝水面斜穿下方背景，密集黑灰人形群像填满上后层，冷白低雾从水面向上过渡，远近分明。','无台词。','冷白水光沿两人的小腿和远处袍下缘描出浅亮，群像上方压深，水面保留细纹。','宽阔低柔水声，衣裙与发丝轻擦，空场短静。'],flags=[],bgmode='physical',new_scene=True)
add('21_002','青向右侧脸近景，长发贴左侧、尖耳在左，领带在下方；右侧留灰色空区。',['青'],[],['头向右','眼睛朝右前','口部微开'],'灰白渐变简化底面',[['你们想要从我们这得到什么?','青','私たちに、何をしてほしいの？'],['还有...你们真的是魔物吗?','青','それと……あんたたち、本当に魔族なの？']],'Mixed，侧脸发问，目光先右前审视，中间停顿后眼稍睁；头不回正。',['青侧脸朝右，唇微开',['头向右前探一点','停顿时下颌收，第二问眼睛稍睁'],'两项盘问从目的转身份，任务是确认而非攻击','侧脸朝右，目光持续审视'],'两短问同一说话方向，十秒自然停顿，第二问有明确表演转折。',9,['75mm平视青向右侧脸近景，尖耳位于左中，长白发沿左侧垂下，白领带在下中，右侧留灰蓝空区；固定机位，口部与眼睛完整。','青向右前方探近一点，嘴唇清晰说出第一问，目光沿右侧审视。短停时下颌微收，眼皮抬开一些，第二问说得更认真；头部始终向右，句末唇合住，眼睛仍扣向右前方。','背景为低亮深灰蓝水域远层，右侧空区柔和较浅，侧脸后的白发轮廓分明。','青说：“私たちに、何をしてほしいの？それと……あんたたち、本当に魔族なの？”（清亮女声，前问直接探查目的，停顿后谨慎确认身份，语速自然。）','冷白柔光照在鼻梁、尖耳和白发，刘海下浅影清楚，蓝领口暗面柔和。','短吸气，发丝在衣领边细擦，低柔水声持续。'],flags=['P','D'],bgrefs=['第20話_21_001.jpg'])
